"""Build portable static pages. All measured values come from data/metrics.json."""
import html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'website'
m=json.loads((ROOT/'data/metrics.json').read_text());repo=m['meta']['repo'];base='https://kushagragupta2005.github.io/gst-evidence-reconciliation/'
PAGES=[('','Home','A factory’s paperwork meets a reality check.'),('problem','The Problem','Why compare factory declarations with evidence from outside the paperwork?'),('how-it-works','How it works','How separate pieces of evidence become a reason for an officer to review.'),('cases','Cases','Follow a caught cheat, an honest exception and a miss from evidence to outcome.'),('results','Results','What the held-out synthetic tests show, and what they cannot tell us.'),('system','System & Stack','Where Exasol fits, how access is guarded, and what the workload timings measure.'),('data','Data & Ethics','Where every record comes from, who can see it and why real use needs lawful access.'),('limits','Limits & Roadmap','What remains untested before this prototype could support real work.')]
def link(slug,prefix):return prefix+(slug+'/index.html' if slug else 'index.html')
def hero(kicker,title,description):return f'<header class="page-hero"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{description}</p></header>'
def card(title,text):return f'<article class="card"><h3>{title}</h3><p>{text}</p></article>'
def nav(slug,prefix):
 main=''.join(f'<a href="{link(s,prefix)}"'+(' aria-current="page"' if s==slug else '')+f'>{t}</a>' for s,t,_ in PAGES if s in ['','cases','results','system'])
 groups=[('Explore',PAGES[:4]),('The proof',PAGES[4:6]),('Responsibility',PAGES[6:])]
 menu=''.join('<div><p class="caption">'+name+'</p>'+''.join(f'<a href="{link(s,prefix)}">{t}</a>' for s,t,_ in entries)+'</div>' for name,entries in groups)
 return f'''<a class="skip" href="#main">Skip to content</a><div class="nav-shell"><nav aria-label="Primary" class="nav"><a class="brand" href="{prefix}index.html"><span class="brand-symbol" aria-hidden="true">≋</span> GST Evidence</a><div class="nav-links">{main}</div><span class="mode" id="mode-pill">Snapshot</span><button class="menu-toggle" aria-expanded="false" aria-controls="explore-menu">Explore <span aria-hidden="true">＋</span></button></nav><div id="explore-menu" class="mega-menu" hidden>{menu}</div></div>'''
def footer(prefix):return f'''<footer><div class="footer-top"><a class="brand" href="{prefix}index.html">GST Evidence</a><p>Built on Exasol Personal.</p></div><div class="footer-links"><span>Kushagra Gupta · Solo project</span><a href="{repo}/blob/main/LICENSE">MIT licence</a><a href="{repo}">Repository ↗</a><a href="{prefix}limits/index.html">Limits & roadmap</a></div><p>All data synthetic. Alerts support human review; they are not findings of fraud.</p><p id="snapshot-stamp" class="caption"></p></footer>'''
content={}
content['']=hero('GST Evidence · Synthetic decision-support prototype','Paperwork meets<br><span>a reality check.</span>','GST Evidence compares factory declarations with power, goods movement, supplier records and bank flows to find contradictions worth a closer look.')+'''<div class="hero-actions"><a class="button" href="cases/index.html">See a case</a><a class="text-link" href="system/index.html">How it’s built <span aria-hidden="true">↗</span></a></div><section class="visual-section" aria-labelledby="chart-title"><div class="visual-heading"><div><p class="eyebrow">One factory. Different stories.</p><h2 id="chart-title">When the lines<br>stop agreeing.</h2></div><p>Recorded dispatch quantities and invoice quantities across the same months. Synthetic evidence, not an illustrative curve.</p></div><div id="hero-visual" class="chart-card"></div></section><section class="reveal"><p class="eyebrow">From scattered evidence to a review list</p><h2>A clearer place<br>to start the week.</h2><p class="section-lede">An officer gets a short list of factories whose paperwork contradicts the evidence, with each contradiction spelled out.</p><div class="grid three steps">'''+card('Collect.','Bring material, power, dispatch, supplier and bank records together.')+card('Compare.','Reconcile declarations against the records from other sources.')+card('Corroborate.','Prioritise a month only when at least two source families fire.')+'''</div></section><section class="reveal"><div class="section-heading"><div><p class="eyebrow">V3-B · held-out synthetic data</p><h2>The result.<br>With the caveats.</h2></div><a class="text-link" href="results/index.html">Explore all results ↗</a></div><div id="home-stats" class="grid three"></div><p class="caption">These are synthetic scenario-recovery measurements. They are not real-world fraud accuracy.</p></section><section class="closing reveal"><h2>A lead to examine.<br>Not a verdict.</h2><a class="button" href="cases/index.html">Follow the evidence</a></section>'''
content['problem']=hero('The problem','The paperwork<br>is only one story.',PAGES[1][2])+f'''<section class="statement"><p class="eyebrow">The project’s problem statement</p><p id="problem-statement">{m['problem_statement']}</p></section><section class="reveal"><h2>Different records.<br>Different questions.</h2><div class="grid three">'''+card('What was declared?','GSTR-1 records outward supplies. Supplier filings also feed the information used for input tax credit (ITC). <a href="https://tutorial.gst.gov.in/userguide/returns/GSTR_1.htm">GST Portal guidance ↗</a>')+card('What moved?','An e-way bill is an electronic record associated with goods movement. It gives this prototype another record to compare with invoices. <a href="https://www.gstn.org.in/e-way-bill">GSTN explanation ↗</a>')+card('What supports the credit?','GSTR-2B helps taxpayers review input tax credit information. This prototype models supplier-return reconciliation; it does not connect to the GST portal. <a href="https://tutorial.gst.gov.in/userguide/returns/FAQ_gstr2b.htm">GST Portal guidance ↗</a>')+'''</div></section><section class="split reveal"><h2>Designed for<br>the GST officer.</h2><div><p>The workflow we target is reviewing declarations when supporting records arrive separately. This is a prototype problem framing, not a claim that every existing tax system ignores these records.</p><p>We test whether cross-source contradictions can make that review more focused, while keeping honest exceptions and missed cheats visible.</p><a class="text-link" href="../how-it-works/index.html">See the method ↗</a></div></section>'''
content['how-it-works']=hero('The method','Corroboration<br>before priority.',PAGES[2][2])+'''<section class="sticky-story"><div class="sticky-visual"><div class="diagram" aria-label="Evidence flows through checks and source families into SQL rules, a priority queue and officer review"><span>Independent records</span><b aria-hidden="true">↓</b><span>Conservation checks</span><b aria-hidden="true">↓</b><span>Source families</span><b aria-hidden="true">↓</b><span class="accent-box">SQL rules → priority queue</span><b aria-hidden="true">↓</b><span>Officer review</span></div></div><div class="story-steps"><article data-step><p class="eyebrow">Production</p><h2>Does the output<br>make sense?</h2><p>Material-to-output and power proxies test declared production. Stock roll-forward checks opening stock, purchases, output, dispatch and closing stock. These checks share one production family.</p></article><article data-step><p class="eyebrow">Movement</p><h2>Did the invoices<br>follow the goods?</h2><p>Dispatch quantities are compared with invoice quantities. Reused e-way identifiers add a movement signal. These are synthetic document records, not independently observed truck journeys.</p></article><article data-step><p class="eyebrow">Supplier</p><h2>Does the other side<br>tell the same story?</h2><p>Purchase quantities are reconciled with supplier returns. Chain tracing records loops as context; a loop alone is not an independent family or proof of fraud.</p></article><article data-step><p class="eyebrow">Financial</p><h2>Do the flows<br>fit the declarations?</h2><p>Bank receipts and payments are compared with declared sales and purchases. Lumpy settlements can be legitimate, so financial discrepancies need context.</p></article></div></section><section class="reveal"><h2>One rule.<br>Human judgment.</h2><div class="grid three">'''+card('SQL decides priority.','At least two source families must exceed the frozen threshold. Several checks in one family still count as one source family.')+card('The note explains.','An optional LLM can draft a note from evidence. The displayed notes use a deterministic fallback and a numeric validator. Neither decides who is flagged.')+card('The officer judges.','A contradiction becomes a review lead. An officer checks the evidence, requests documents and decides what action is justified.')+'''</div><p id="rule-parameters" class="caption"></p><p>“Independent” describes the source grouping in the prototype. Causal independence has not been established.</p></section>'''
content['cases']=hero('Case explorer','Every outcome<br>has a reason.',PAGES[3][2])+'''<section class="case-section"><div class="case-picker" role="group" aria-label="Choose a case"><button data-case="0" aria-pressed="true">Caught cheat</button><button data-case="1" aria-pressed="false">Honest exception</button><button data-case="2" aria-pressed="false">Miss</button></div><div id="case-content" aria-live="polite"></div></section><section class="reveal"><p class="eyebrow">Guarded follow-up</p><h2>Ask a question.<br>Inspect the answer.</h2><p class="section-lede">Choose a fixed read-only query. On this public site the answer is recorded; a local restricted API can execute the same template live.</p><div id="questions" class="chips"></div><div id="answer" class="card" aria-live="polite"></div><details id="activity-panel" hidden><summary>Live executed-query activity</summary><button id="activity-refresh">Refresh activity</button><div id="activity"></div></details></section>'''
content['results']=hero('Results · synthetic data','Measured.<br>Including the misses.',PAGES[4][2])+'''<section class="results-section"><div class="seed-control" role="group" aria-label="Held-out dataset"><button data-seed="v3_b" aria-pressed="true">V3-B · primary</button><button data-seed="v3_c" aria-pressed="false">V3-C · confirmation</button></div><p id="seed-description" class="caption"></p><h2>Monthly outcomes.</h2><div id="result-stats" class="grid three" aria-live="polite"></div><article class="card measurement"><h2>How we measured.</h2><p>The development seed chose the threshold and factory queue rule. The held-out seeds test those frozen choices. Monthly recall asks how many active cheat months were flagged. False-positive rate asks how many honest months were flagged.</p><p>The confidence intervals resample whole factories, preserving their months together. They describe sampling uncertainty within this synthetic design, not accuracy on real taxpayers.</p><p id="measurement-protocol"></p></article></section><section class="reveal"><h2>Months and factories<br>answer different questions.</h2><p>A factory enters the queue only after enough prioritised months. This is different from flagging an individual month.</p><div id="factory-stats" class="grid three"></div></section><section class="reveal"><h2>What does zero<br>actually tell us?</h2><div id="wrong-clear" class="card"></div></section><section class="reveal"><h2>Take one check away.</h2><p>Leave-one-check-out recall with every other check still present. A small change can reflect overlapping evidence, not a useless check. Post-hoc point estimates only; ablation intervals remain unmeasured.</p><div id="ablation" class="card"></div></section><section class="reveal"><h2>When cheating<br>is less common.</h2><p>Precision changes with prevalence. This analytic reweighting holds sensitivity and false-positive rate fixed; it is not a new low-prevalence experiment.</p><div id="prevalence"></div></section><section class="reveal"><h2>The errors matter.</h2><div id="decoys"></div><p>Paired before/after-clearing decoy FPR and stock-aware/evasive subgroup comparisons remain unmeasured.</p><a href="../limits/index.html" class="text-link">Read every limitation ↗</a></section>'''
content['system']=hero('System & stack','Evidence in.<br>Review leads out.',PAGES[5][2])+'''<section class="reveal"><h2>From records to review.</h2><div class="architecture" aria-label="System architecture"><div class="card"><p class="eyebrow">Inputs</p><h3>Seeded evidence CSVs</h3><p>Declarations, movement, power, supplier records and bank flows.</p></div><span aria-hidden="true">→</span><div class="card"><p class="eyebrow">Primary database</p><h3>Exasol Personal</h3><p>GST_EVIDENCE schema. Joins, windows, checks and family aggregation.</p></div><span aria-hidden="true">→</span><div class="card"><p class="eyebrow">Decision support</p><h3>Cases and notes</h3><p>Restricted API → evidence views → validated explanation → officer.</p></div></div><p>Evaluator-only truth stays outside the detector and restricted API. Public Pages runs entirely from recorded artifacts.</p></section><section class="split reveal"><h2>SQL does<br>the reconciliation.</h2><div><p>V_FEATURES contains the per-check measurements. V_ALL_EVIDENCE retains rows above the threshold. V_RANKED_CASES groups source families into monthly priorities. V_SINGLE_SIGNAL_DISPOSITIONS explains single-family exceptions.</p><p>Window functions provide prior stock and operational baselines. The site does not claim a deployed Python UDF or an operational MCP integration; the demonstrated follow-up path uses guarded SELECT templates.</p><a data-repo-file="sql/10_checks.sql">Read the detector SQL ↗</a></div></section><section class="reveal"><h2>Access is<br>deliberately narrow.</h2><div class="grid three">'''+card('Restricted reader.','The local API connects only through an account with session, schema usage and explicit SELECT grants on label-free views. It cannot read truth labels.')+card('Guarded questions.','Only dispatch, timeline and evidence intents compile to fixed SELECT templates. Row limits, timeouts and rate limits bound the API.')+card('Evidence-only notes.','A validator checks numeric claims against evidence rows. An optional LLM draft can be rejected. The recorded notes are the labeled deterministic fallback.')+'''</div></section><section class="reveal"><h2>The workload.<br>The actual timings.</h2><p>Workload timings on the author’s MacBook. Synthetic data. No general engine speed claim.</p><div id="scale-stats" class="grid three"></div><div id="comparison"></div><p>DuckDB was faster for both recorded checks. Its CSV loading is measured separately; Exasol ingestion was not remeasured. Different physical plans and execution environments limit the comparison.</p><div id="scale-provenance"></div><details><summary>Historical scale run</summary><p id="historical-scale"></p></details></section><section class="reveal"><h2>Reproduce<br>what is here.</h2><p>Install Exasol Personal using its official instructions, then follow the repository README. Database provisioning and regeneration need the documented loader permissions; the site’s Live API remains read-only.</p><pre class="command">sh scripts/bootstrap.sh
make provision-reader
make test
make reproduce
make site
# In another terminal:
make api</pre><a class="button" data-repo-file="README.md">Open the reproduction guide</a></section>'''
content['data']=hero('Data & ethics','Synthetic by design.<br>Explicit about access.',PAGES[6][2])+'''<section class="reveal"><h2>Generated here.<br>Not collected from taxpayers.</h2><p>A seeded Python generator creates factories, suppliers, monthly stock and power records, invoices, purchase invoices, e-way bills, supplier returns, bank entries, machines and supporting documents. All records and verification statuses are synthetic.</p><div id="data-inventory"></div><a data-repo-file="src/generate.py">Inspect the generator ↗</a></section><section class="grid three reveal">'''+card('Planted cheats.','Hidden production, inflated ITC through supplier discrepancies, and e-way reuse are planted at different intensities. Evasive cases may remain visible in only one family.')+card('Honest exceptions.','Machinery upgrades, product-mix changes, longer hours, seasonal stock build, new suppliers and lumpy bank flows test false alarms.')+card('Labels kept apart.','Truth labels describe planted scenarios for offline scoring. They are not features in detector SQL and are not accessible through the restricted API.')+'''</section><section class="split reveal"><h2>Real access<br>would change the work.</h2><div><p>The roadmap starts with tax-system data: invoices, e-way bills and supplier returns. Power and bank data would follow only under lawful, proportionate access.</p><p>Real use needs purpose limits, access auditing, retention controls, privacy assessment and human review before any action affecting a taxpayer.</p><p>No real taxpayer data has been evaluated. A synthetic “verified” document is generator metadata, not an independent verification service.</p></div></section><section class="reveal"><h2>Sources and licences.</h2><div class="grid three">'''+card('Project and data.','Project code is MIT-licensed. The synthetic datasets come from this repository’s script. <a data-repo-file="LICENSE">Project licence ↗</a>')+card('Tools.','Exasol Personal is the primary database under its EULA. Python, PyExasol and the optional DuckDB comparison have their own licences. Playwright, axe and Lighthouse are development-only verification tools; the pages use no runtime framework. <a data-repo-file="THIRD_PARTY.md">Dependency inventory ↗</a>')+card('AI assistance.','AI coding assistants helped build the project. The optional OpenAI API is subject to its service terms; the public notes shown here use deterministic generation. <a data-repo-file="README.md">Disclosure and APIs ↗</a>')+'''</div></section>'''
content['limits']=hero('Limits & roadmap','Know what<br>is still unknown.',PAGES[7][2])+'''<section class="grid two reveal">'''+card('Synthetic recovery only.','Held-out tests share the same generator family. They do not demonstrate real taxpayer accuracy or causal independence of evidence families.')+card('False positives and misses.','Honest factories can be flagged. Evasive cheats can remain below threshold or fire only one family. Alerts support human review; they are not findings of fraud.')+card('Verification is generated.','Document status is synthetic metadata. A sophisticated-forger test remains unimplemented. A zero-event rule-of-three bound assumes independent factory outcomes.')+card('Uncertainty gaps.','Ablation intervals, wrong-clear cluster-bootstrap intervals, paired before/after clearing metrics, and stock-aware/evasive comparisons remain unmeasured.')+card('Scale is unfinished.','The large scale artifact is historical. The fresh comparison covers the current smaller dataset; DuckDB was faster. A new full-scale load and larger concurrency test remain pending.')+card('Reproduction is local.','The author-machine fresh-clone run is documented at its original commit. A second-machine database reproduction and a fresh clone of this new presentation remain unverified.')+'''</section><section class="reveal"><h2>The next useful steps.</h2><ol class="roadmap"><li><h3>Challenge the verifier.</h3><p>Predeclare a sophisticated-forger scenario and measure wrong-clears with factory-aware uncertainty.</p></li><li><h3>Extend the measurement.</h3><p>Add ablation intervals, a regenerated low-prevalence evaluation and a stamped full-scale run under authorised loader access.</p></li><li><h3>Reproduce elsewhere.</h3><p>Run the documented setup on another machine and record every failure.</p></li><li><h3>Validate lawful data access.</h3><p>Start with tax-system evidence, then assess power and bank data access and privacy controls.</p></li></ol><p>No operational deployment, working UDF or MCP demo is implied. Case data remain recorded; only guarded local follow-ups can run live.</p><a data-repo-file="LIMITATIONS.md">Full limitations register ↗</a></section>'''
content['limits']=content['limits'].replace('<section class="grid two reveal">','<section class="reveal"><h2>Current limits.</h2><div class="grid two">',1).replace('</section><section','</div></section><section',1)
for slug,title,description in PAGES+[('404','Page not found','This page is not part of the evidence trail.')]:
 prefix='../' if slug and slug!='404' else './'
 folder=OUT/slug if slug and slug!='404' else OUT;folder.mkdir(parents=True,exist_ok=True)
 canonical=base+(slug+'/' if slug and slug!='404' else '')
 body=content.get(slug,hero('Page not found','Let’s get back<br>to the evidence.',description)+f'<a class="button" href="{base}">Go to Home</a>')
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>{title} — GST Evidence</title><meta name="description" content="{html.escape(description,quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{title} — GST Evidence"><meta property="og:description" content="{html.escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{base}assets/og.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="{base}assets/og.png"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}style.css"><script defer src="{prefix}metrics.js"></script><script defer src="{prefix}site.js"></script></head><body data-page="{slug or 'home'}" data-root="{prefix}">{nav(slug,prefix)}<main id="main">{body}</main>{footer(prefix)}</body></html>'''
 # Use absolute assets in the fallback page because its requested path is unknown.
 if slug=='404':page=page.replace('href="./','href="'+base).replace('src="./','src="'+base)
 (folder/('404.html' if slug=='404' else 'index.html')).write_text(page)
(OUT/'assets').mkdir(exist_ok=True)
(OUT/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#0071e3"/><path d="M16 20h32M16 32h24M16 44h32" stroke="white" stroke-width="5" stroke-linecap="round"/></svg>')
(OUT/'assets/og.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630"><rect width="1200" height="630" fill="#f5f5f7"/><g font-family="Helvetica,Arial,sans-serif"><text x="80" y="100" font-size="26" fill="#515154">GST Evidence · Built on Exasol Personal</text><text x="75" y="275" font-size="88" font-weight="700" fill="#1d1d1f">Paperwork meets</text><text x="75" y="380" font-size="88" font-weight="700" fill="#0071e3">a reality check.</text><text x="80" y="535" font-size="26" fill="#515154">Synthetic evidence. Explainable contradictions. Human review.</text></g></svg>')
print('Built eight pages, a fallback page and share-image source.')
